style.css:
@-moz-document domain("crm.abil.company") {
/* 1. Inversão Inteligente (Rápido e Eficaz) */
    html {
        filter: invert(0.9) hue-rotate(180deg) !important;
        background: #121212 !important;
    }

    /* 2. Reverter imagens, vídeos e ícones para cores originais */
    img, video, iframe, [style*="background-image"], .icon, .avatar {
        filter: invert(1) hue-rotate(180deg) !important;
    }

    /* 3. Ajustes de Contraste e Texto */
    body {
        text-shadow: 0 0 0.1px rgba(255,255,255,0.1); /* Suaviza fontes */
    }

    /* 4. Correção para áreas que devem permanecer escuras */
    input, select, textarea {
        background-color: #f0f0f0 !important;
        color: #000 !important;
    }

    /* Ajuste de links para melhor visibilidade */
    a {
        color: #3399ff !important;
    }
}
